-- State transitions declared for UserSAMLLink (shadow: an undeclared move raises a WARNING).
-- Generated by metaphor-schema

CREATE OR REPLACE FUNCTION sapiens.user_saml_links_status_transition_check() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF NEW."status" IS DISTINCT FROM OLD."status" AND NOT (
           (COALESCE(OLD."status"::text, ''), COALESCE(NEW."status"::text, '')) IN (('active', 'inactive'), ('inactive', 'active'))
       ) THEN
        RAISE WARNING 'state_transition_not_declared: user_saml_links.status % -> %', OLD."status", NEW."status";
    END IF;
    RETURN NEW;
END $$;

DROP TRIGGER IF EXISTS user_saml_links_status_transition_check ON sapiens.user_saml_links;
CREATE TRIGGER user_saml_links_status_transition_check
    BEFORE UPDATE OF "status" ON sapiens.user_saml_links
    FOR EACH ROW EXECUTE FUNCTION sapiens.user_saml_links_status_transition_check();
